type Obj = Record<string, unknown>;
const obj = ((row["data"] as { object?: Obj } | undefined)?.object ?? {}) as Obj;
const sessionId = typeof obj["id"] === "string" ? obj["id"] : "";
if (!sessionId || obj["payment_status"] !== "paid") { ctx.log(`stripe: checkout ${sessionId || "(no id)"} not paid yet — nothing recorded`); return; }
const known = await ctx.db.list("stripe_payment", { filter: { session_id: sessionId }, limit: 1 });
if (known.length > 0) { ctx.log(`stripe: checkout ${sessionId} already recorded`); return; }
const details = (obj["customer_details"] ?? {}) as { email?: string | null; name?: string | null };
const meta = (obj["metadata"] ?? {}) as Record<string, string>;
await ctx.db.create("stripe_payment", {
  session_id: sessionId,
  amount: Number(obj["amount_total"] ?? 0) / 100,
  currency: String(obj["currency"] ?? "usd").toUpperCase(),
  email: details.email ?? null,
  payer_name: details.name ?? "",
  description: meta["description"] ?? "",
  paid_at: new Date((Number(obj["created"] ?? 0) || Math.floor(ctx.now().getTime() / 1000)) * 1000).toISOString(),
});
ctx.log(`stripe: checkout ${sessionId} recorded`);

const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Stripe isn't connected yet. Connect Stripe in the builder or add STRIPE_SECRET_KEY in the project settings.");
const res = await ctx.http.fetch("https://api.stripe.com/v1/checkout/sessions?limit=50&status=complete", { headers: { authorization: `Bearer ${key}` } });
if (!res.ok) throw new Error(`Stripe answered ${res.status}. Check the key in the project settings.`);
type Session = { id: string; payment_status?: string; amount_total?: number | null; currency?: string | null; created?: number; customer_details?: { email?: string | null; name?: string | null } | null; metadata?: Record<string, string> | null };
const sessions = (res.json<{ data?: Session[] }>()?.data ?? []).filter((s) => s.payment_status === "paid");
const known = new Set((await ctx.db.list("stripe_payment", { limit: 1000 })).map((r) => String(r["session_id"])));
let added = 0;
for (const s of sessions) {
  if (known.has(s.id)) continue;
  await ctx.db.create("stripe_payment", {
    session_id: s.id,
    amount: (s.amount_total ?? 0) / 100,
    currency: (s.currency ?? "usd").toUpperCase(),
    email: s.customer_details?.email ?? null,
    payer_name: s.customer_details?.name ?? "",
    description: s.metadata?.["description"] ?? "",
    paid_at: new Date((s.created ?? 0) * 1000).toISOString(),
  });
  added++;
}
ctx.log(`stripe: ${sessions.length} paid sessions checked, ${added} new`);
return { checked: sessions.length, added };

